class Cart:
    def __init__(self, free_shipping_threshold: float = 100.0, shipping_cost: float = 15.0) -> None:
        self.free_shipping_threshold = free_shipping_threshold
        self.shipping_cost = shipping_cost
        self._items = []  # list of (name, unit_price, quantity)
        self._discounts = []  # list of percent
        self._vouchers = []  # list of amount

    def add(self, name: str, unit_price: float, quantity: int = 1) -> None:
        if quantity <= 0:
            raise ValueError("Quantity must be greater than zero")
        self._items.append((name, unit_price, quantity))

    def apply_discount(self, percent: float) -> None:
        self._discounts.append(percent)

    def apply_voucher(self, amount: float) -> None:
        self._vouchers.append(amount)

    def total(self) -> float:
        items_total = sum(unit_price * quantity for _, unit_price, quantity in self._items)

        # Honor free shipping threshold based on pre-discount item value
        if items_total >= self.free_shipping_threshold:
            shipping = 0.0
        else:
            shipping = self.shipping_cost

        # Compute total savings for each option; pick the single best one
        best_savings = 0.0

        for percent in self._discounts:
            savings = items_total * (percent / 100.0)
            # A discount can't exceed the item value
            savings = min(savings, items_total)
            if savings > best_savings:
                best_savings = savings

        for amount in self._vouchers:
            # Voucher caps at items_total; unused portion is lost
            savings = min(amount, items_total)
            if savings > best_savings:
                best_savings = savings

        items_after = items_total - best_savings
        # Guard against negative due to floating point
        if items_after < 0:
            items_after = 0.0

        return items_after + shipping

